import{_ as a,o as t,c as r,a5 as i}from"./chunks/framework.BF53ZjCA.js";const g=JSON.parse('{"title":"Physical Tests","description":"","frontmatter":{"title":"Physical Tests","identification":"physical-tests"},"headers":[],"relativePath":"identification/physical-tests.md","filePath":"identification/physical-tests.md","lastUpdated":1790876393000}'),n={name:"identification/physical-tests.md"};function s(o,e,l,c,d,p){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="physical-tests" tabindex="-1">Physical Tests <a class="header-anchor" href="#physical-tests" aria-label="Permalink to &quot;Physical Tests&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Refractive index, specific gravity, hardness, and cleavage are the most basic identification tools — influenced by chemistry and crystal structure, so each species tends to fall within a comparable range; conditions, orientation, treatment, and sample state can shift the reading.</p><aside class="gem-identification-boundary" aria-labelledby="identification-boundary-physical-tests-en"><p class="gem-identification-boundary__eyebrow">IDENTIFICATION BOUNDARY</p><h2 id="identification-boundary-physical-tests-en">Boundary &amp; Safety</h2><p>This page is an educational testing framework, not an operating authorization outside instrument instructions, training, and sample conditions. Record RI/SG as typical or measured ranges; hardness testing can damage a specimen. Skip unsuitable tests for mounted, tiny, porous, fragile, or high-value samples and consider lab referral. </p></aside><h2 id="identification-steps" tabindex="-1">Identification Steps <a class="header-anchor" href="#identification-steps" aria-label="Permalink to &quot;Identification Steps&quot;">​</a></h2><p><strong>Shared teaching protocol</strong></p><p>Read every test in the same order: purpose → suitability → operation and record → interpretation → exception handling → risk/lab referral. Reference values narrow candidates; they are not a specimen “code”.</p><table tabindex="0"><thead><tr><th>Test</th><th>Primary output</th><th>Typical limits</th></tr></thead><tbody><tr><td>RI</td><td>Point/range, direction, reading quality</td><td>Curvature, size, transparency, contact, and range</td></tr><tr><td>SG</td><td>Method, value, repeats</td><td>Mounting, porosity, absorption, bubbles, and mass</td></tr><tr><td>Mohs hardness</td><td>Scratch observation</td><td>Destructive and relative; not authenticity or durability</td></tr><tr><td>Cleavage</td><td>Structural risk record</td><td>Never verify by striking or splitting</td></tr></tbody></table><h3 id="_1-refractive-index-ri" tabindex="-1">1. Refractive index (RI) <a class="header-anchor" href="#_1-refractive-index-ri" aria-label="Permalink to &quot;1. Refractive index (RI)&quot;">​</a></h3><p><strong>Purpose:</strong> Narrow material candidates with RI and optical information.</p><p><strong>Suitability:</strong> Confirm the refractometer is usable, clean the specimen and contact surface, and check whether size, curvature, and transparency suit the measurement. Record mounted, tiny, or inaccessible specimens as unsuitable when reliable contact is not possible.</p><p><strong>Operation and record:</strong> Record a point or range, viewing direction, contact state, reading quality, and repeat stability. Preserve raw readings instead of recording only a rounded “answer”.</p><p><strong>Interpretation:</strong> Compare the reading with typical candidate ranges, birefringence, and sample state. RI can support or exclude candidates; it cannot by itself establish natural, synthetic, or treatment status.</p><p><strong>Exception handling:</strong> If the reading is out of range, blurred, poorly contacted, or unstable, record that it is unreliable and why, then choose a suitable non-destructive observation.</p><p><strong>Risk/referral:</strong> Do not repeatedly press or contaminate a specimen just to obtain a name. Preserve raw records and refer high-value, formal-disclosure, or conflicting cases.</p><h3 id="_2-specific-gravity-sg" tabindex="-1">2. Specific gravity (SG) <a class="header-anchor" href="#_2-specific-gravity-sg" aria-label="Permalink to &quot;2. Specific gravity (SG)&quot;">​</a></h3><p><strong>Purpose:</strong> Use the mass-to-volume relationship as supporting evidence for a candidate.</p><p><strong>Suitability:</strong> Decide whether a liquid or hydrostatic method suits the sample. Mounting, porosity, absorption, surface damage, very small size, and composite structure can distort the result.</p><p><strong>Operation and record:</strong> Follow equipment, liquid, and laboratory safety instructions. Record method, sample state, environment, repeats, bubbles, contact fixtures, and corrections. Do not turn one unchecked weighing into a certain value.</p><p><strong>Interpretation:</strong> Cross-check SG with RI, optical behavior, microscopy, and candidate ranges; one SG value does not map directly to a gem name.</p><p><strong>Exception handling:</strong> If bubbles, contamination, absorption, fixture interference, or large repeat differences occur, mark the result unreliable and stop using it to exclude candidates.</p><p><strong>Risk/referral:</strong> Handle liquids, specimens, and waste according to equipment instructions and safety data. Skip liquid testing for unsuitable or valuable specimens and consider referral.</p><h3 id="_3-mohs-hardness" tabindex="-1">3. Mohs hardness <a class="header-anchor" href="#_3-mohs-hardness" aria-label="Permalink to &quot;3. Mohs hardness&quot;">​</a></h3><p><strong>Purpose:</strong> When explicitly authorized and risk is acceptable, record relative scratch resistance.</p><p><strong>Suitability:</strong> Hardness is not a first choice. Default to no scratch test for valuable, mounted, visibly fractured, fragile, or surface-treated samples.</p><p><strong>Operation and record:</strong> If authorized, record location, tool, direction, and whether a scratch was observed; absence of a scratch is not proof of authenticity.</p><p><strong>Interpretation:</strong> Mohs hardness is relative scratch resistance, not authenticity, durability, transparency, or value; operator and surface conditions affect observations.</p><p><strong>Exception handling:</strong> If the result is unclear, the surface is already damaged, or the tool condition is unknown, record that no reliable hardness result was obtained and do not add damage.</p><p><strong>Risk/referral:</strong> Stop whenever risk exceeds the value of educational screening; formal identification and disclosure belong to a qualified laboratory.</p><h3 id="_4-cleavage-and-breakage-risk" tabindex="-1">4. Cleavage and breakage risk <a class="header-anchor" href="#_4-cleavage-and-breakage-risk" aria-label="Permalink to &quot;4. Cleavage and breakage risk&quot;">​</a></h3><p><strong>Purpose:</strong> Recognize structural breakage risk, not create a fracture as evidence.</p><p><strong>Suitability:</strong> Record structural clues, visible fissures, and sample state; describe cleavage, fracture, fissures, and existing damage separately.</p><p><strong>Operation and record:</strong> Record directional structural clues, existing damage, and inaccessible tests. Never strike, split, or force a specimen to verify cleavage.</p><p><strong>Interpretation:</strong> Cleavage is a structural breakage tendency; it is not necessarily visible in a finished gem and cannot name a specimen alone.</p><p><strong>Exception handling:</strong> If structural risk is unclear or looseness/fissure growth appears, stop contact tests immediately and record the state.</p><p><strong>Risk/referral:</strong> For diamond and other high-risk specimens, treat cleavage as a stop signal and refer the sample to a qualified professional.</p><h2 id="core-principles" tabindex="-1">Core Principles <a class="header-anchor" href="#core-principles" aria-label="Permalink to &quot;Core Principles&quot;">​</a></h2><ul><li>RI and SG are conditional typical references or measured ranges; direction, instrument, contact, treatment, and sample state affect readings.</li><li>Hardness is relative scratch resistance, not authenticity, durability, or value; scratch testing can damage a specimen.</li><li>Cleavage is a structural breakage tendency; never verify it by striking or splitting and do not assume it is visibly present.</li><li>Interpret every reading with sample state, repeats, and other evidence; never compare it without context.</li></ul><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Gem</th><th>Value</th><th>Note</th></tr></thead><tbody><tr><td>diamond</td><td>RI 2.42; SG 3.52</td><td>Typical reference; combine with conditions and other evidence</td></tr><tr><td>ruby</td><td>RI 1.762–1.770; SG 4.00 ± 0.05</td><td>Typical corundum reference; not a standalone ID</td></tr></tbody></table><aside class="gem-reference-block" aria-labelledby="gem-reference-title"><p class="gem-reference-block__eyebrow">SOURCE TRACE</p><h2 id="gem-reference-title">References &amp; Evidence Boundary</h2><p class="gem-reference-block__intro">This page supports learning and retrieval; the sources document the knowledge basis and do not make this page sufficient for identifying a specific specimen.</p><ul><li><a href="https://www.gia.edu/gems-gemology/winter-2024-gemstone-analysis" target="_blank" rel="noreferrer">GIA: Analysis of Gemstones at GIA Laboratories</a><span>Standard gemological testing, laboratory workflow, and laboratory-grown diamond analysis examples</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/gems-gemology/winter-2019-analytical-methods-geographic-origin-determination-gemstones" target="_blank" rel="noreferrer">GIA: Analytical Methods Used in Geographic Origin Determination</a><span>RI/SG as an identification starting point and further analysis for origin opinions</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/gems-gemology/winter-2024-infrared-spectroscopy" target="_blank" rel="noreferrer">GIA: Infrared Spectroscopy and Its Use in Gemology</a><span>Spectroscopy and its relationship to atomic structure and natural/synthetic/treatment clues</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/ruby" target="_blank" rel="noreferrer">GIA Gem Encyclopedia: Ruby</a><span>Typical ruby RI, birefringence, specific gravity, and hardness references</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/sapphire" target="_blank" rel="noreferrer">GIA Gem Encyclopedia: Sapphire</a><span>Typical sapphire RI, birefringence, specific gravity, and hardness references</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/emerald" target="_blank" rel="noreferrer">GIA Gem Encyclopedia: Emerald</a><span>Typical emerald RI, birefringence, specific gravity, hardness, and treatment/synthetic/imitation context</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/spinel" target="_blank" rel="noreferrer">GIA Gem Encyclopedia: Spinel</a><span>Typical spinel RI, isotropy, specific gravity, and hardness references</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/diamond" target="_blank" rel="noreferrer">GIA Gem Encyclopedia: Diamond</a><span>Typical diamond RI, specific gravity, and hardness references</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/zircon" target="_blank" rel="noreferrer">GIA Gem Encyclopedia: Zircon</a><span>Typical zircon RI, birefringence, specific gravity, and hardness references</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/articles/iolite-description" target="_blank" rel="noreferrer">GIA: Iolite Description</a><span>Iolite pleochroism and viewing-direction context</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/tanzanite-description" target="_blank" rel="noreferrer">GIA: Tanzanite Description</a><span>Tanzanite pleochroism, orientation, lighting, and heat-treatment context</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/peridot" target="_blank" rel="noreferrer">GIA Gem Encyclopedia: Peridot</a><span>Typical peridot RI, birefringence, specific gravity, and hardness references</span><small>Open source ↗</small></li><li><a href="https://my.gia.edu/FAQ/gia-faq-two-green-garnet" target="_blank" rel="noreferrer">GIA FAQ: Tsavorite and Demantoid</a><span>Green garnet colour overlap and mineral distinction context</span><small>Open source ↗</small></li></ul></aside><p><em>See the <a href="./intro.html">identification overview</a>.</em></p>',42)])])}const u=a(n,[["render",s]]);export{g as __pageData,u as default};
